// The VPU-mixer model, and the derivations built on it.
//
// Pure: no Node APIs, no DOM. The browser imports this directly and the server
// imports it too, so a live read and a recorded capture go through identical
// code on their way to the screen.
//
// A "VPU" on a LivePremier is a *VPU mixer*: the physical mixing/scaling
// resource the device allocates to a (screen, layer) pair. A layer too wide for
// one mixer is split across several, each carrying one `slice`. That is why the
// mixer table — not the layer count — is the real answer to "will this fit".

export const PROCESSORS = 4;
export const MIXERS_PER_PROCESSOR = 16;
export const MAX_MIXERS = PROCESSORS * MIXERS_PER_PROCESSOR; // 64

/** Every mixer id the model allows, in chassis order. */
export const MIXER_IDS = (() => {
  const ids = [];
  for (let p = 1; p <= PROCESSORS; p++) {
    for (let m = 1; m <= MIXERS_PER_PROCESSOR; m++) ids.push(`PROC_${p}_MIXER_${m}`);
  }
  return ids;
})();

export const SCALERS = ['A', 'B'];

/** Output pipes per mixer — one per output link. */
export const OUT_PIPES = 8;

/** Props read from each mixer. All are readOnly in the device's own model. */
export const MIXER_PROPS = [
  'isEnabled',
  'cutnfillCapa',
  'usedInScreen',
  'usedInLayer',
  'channel',
  'slice',
  'capability',
  'seamlessCapa',
];

export const LAYER_CAPABILITIES = ['OFF', 'DUAL', '4K', '3', '5K', '5', '6', '7', '8K'];

export function parseMixerId(id) {
  const m = /^PROC_(\d+)_MIXER_(\d+)$/.exec(id);
  if (!m) return null;
  return { processor: Number(m[1]), index: Number(m[2]) };
}

/**
 * Derive the summary the UI leads with: how much hardware is fitted, how much
 * is spent, and which (screen, layer) runs it was spent on.
 */
export function summarise(mixers) {
  const entries = Object.entries(mixers || {});
  const fitted = entries.filter(([, r]) => r && r.isAvailable);
  const enabled = fitted.filter(([, r]) => r.isEnabled);

  const processors = new Map();
  for (const [id, rec] of entries) {
    const parsed = parseMixerId(id);
    if (!parsed) continue;
    if (!processors.has(parsed.processor)) {
      processors.set(parsed.processor, { processor: parsed.processor, fitted: 0, enabled: 0 });
    }
    const bucket = processors.get(parsed.processor);
    if (rec && rec.isAvailable) bucket.fitted++;
    if (rec && rec.isEnabled) bucket.enabled++;
  }

  // Group enabled mixers into the (screen, layer) runs a layer actually costs.
  const groups = new Map();
  for (const [id, rec] of enabled) {
    const key = `${rec.usedInScreen} ${rec.usedInLayer}`;
    if (!groups.has(key)) {
      groups.set(key, {
        screen: rec.usedInScreen,
        layer: rec.usedInLayer,
        capability: rec.capability,
        mixers: [],
        slices: [],
        pipes: new Set(),
      });
    }
    const g = groups.get(key);
    g.mixers.push(id);
    g.slices.push(rec.slice);
    const a = rec.mixerAllocation || {};
    for (let k = 1; k <= OUT_PIPES; k++) {
      const v = a[`usedOnOutPipe${k}`];
      if (v !== undefined && v !== null && v !== 'NONE') g.pipes.add(`link ${k}\u2192out ${v}`);
    }
  }

  const allocations = [...groups.values()]
    .map((g) => ({ ...g, slices: [...g.slices].sort((a, b) => a - b), pipes: [...g.pipes] }))
    .sort((a, b) => {
      const sa = String(a.screen);
      const sb = String(b.screen);
      if (sa !== sb) return sa.localeCompare(sb, undefined, { numeric: true });
      if (a.layer === 'NATIVE') return -1;
      if (b.layer === 'NATIVE') return 1;
      return String(a.layer).localeCompare(String(b.layer), undefined, { numeric: true });
    });

  return {
    fitted: fitted.length,
    enabled: enabled.length,
    spare: fitted.length - enabled.length,
    max: MAX_MIXERS,
    screens: new Set(allocations.map((a) => a.screen)).size,
    processors: [...processors.values()].sort((a, b) => a.processor - b.processor),
    allocations,
  };
}

/* ------------------------------------------------------------------------ *
 * The link grid — the way Analog Way's own manual draws a VPU.
 *
 * A VPU is an 8x8 field of links: 8 layer links in on the left, 8 output links
 * out through the top and bottom (User Manual v6.0 §5.5). A layer occupies a
 * square block sized by its capacity — capacity 1 is 1x1 links, capacity 2 is
 * 2x2, capacity 4 is 4x4 — so a VPU holds 64 capacity-1 layers, 16 capacity-2
 * ones, or 4 capacity-4 ones.
 *
 * §5.5.4: a VPU spreads a layer over at most 4 output links. A layer wider than
 * that consumes a second layer link and wraps onto it.
 *
 * ---------------------------------------------------------------------------
 * HOW MUCH OF THIS THE DEVICE ACTUALLY REPORTS — settled on hardware 2026-08-21.
 *
 * COLUMNS ARE REPORTED. `mixerAllocation.usedOnOutPipe1..8` names exactly which
 * output links a mixer drives. Every mixer in a (screen, layer) run shares the
 * same set, and different runs sit on different links — on the captured Aquilon C,
 * S1 on links 1 and 3, S3 on 2 and 4, S2 on 5 and 7. Note the interleaving: runs
 * are NOT allocated contiguous links, so the grid must draw what is reported
 * rather than forcing each mixer into a contiguous square.
 *
 * ROWS ARE NOT. Nothing names the layer link. Two layers of one screen share both
 * their output links and their slice numbers — S4's native and its layer 1 are
 * identical on both counts — so slice cannot separate them. `channel` reads 0 on
 * every mixer and is no help either. `buildLinkGrid` therefore packs rows.
 *
 * `$vpuLayer` — which looked like the reported grid, 8 scalers per VPU each
 * declaring 8 output pipes — DOES NOT EXIST on hardware: it answers E12, along
 * with `$pipe`. It is present but permanently empty on the simulator. The two
 * implementations expose different collections; trust the hardware.
 * ------------------------------------------------------------------------ */

export const LINKS_PER_VPU = 8;
export const SCALING_ENGINE_BOUNDARY = 4; // output links, §5.5.4

/**
 * How many links square one layer of a given capability occupies.
 *
 * The device's own LAYER_CAPABILITIES enum is `OFF, DUAL, 4K, 3, 5K, 5, 6, 7,
 * 8K` — and read as a list, its *position* is the capacity: the plain numeric
 * entries sit at exactly their own index (`3` third, `5` fifth, and so on), so
 * the named ones are the capacities that got names. DUAL is 1, 4K is 2, 5K is
 * 4, 8K is 8. The manual only discusses capacities 1, 2 and 4 (§5.5.3).
 *
 * This was originally hard-coded with `8K` at 4 and no entry for `5K` at all,
 * which a chassis reporting `5K` showed up as wrong.
 *
 * Note this only sizes blocks in the DERIVED fallback layout — where the device
 * reports its output links, block position comes from those instead.
 */
export function capacityToLinks(capability) {
  if (capability === 'OFF' || capability === undefined || capability === null) return 0;
  const i = LAYER_CAPABILITIES.indexOf(String(capability));
  if (i > 0) return i;
  const n = Number(capability);
  return Number.isFinite(n) && n > 0 ? n : 2;
}

/** The output-pipe slots a mixer drives, 0-based, as reported by the device. */
export function reportedColumns(rec) {
  const a = (rec && rec.mixerAllocation) || {};
  const cols = [];
  for (let k = 1; k <= OUT_PIPES; k++) {
    const v = a[`usedOnOutPipe${k}`];
    if (v !== undefined && v !== null && v !== 'NONE') cols.push(k - 1);
  }
  return cols;
}

/**
 * Build the link grid, using the device's own output-pipe allocation for the
 * columns and deriving only the rows.
 *
 * WHAT IS REPORTED: `mixerAllocation.usedOnOutPipe1..8` names exactly which
 * output links a mixer drives, and every mixer in a (screen, layer) run shares
 * the same set. So horizontal position is the device's, not ours.
 *
 * WHAT IS NOT: nothing identifies the layer link — the row. Two layers of one
 * screen legitimately share both their pipes and their slice numbers (a screen's
 * native and its layer 1 composite onto the same outputs), so slice alone cannot
 * separate them. Rows are therefore assigned by packing: a run occupies one row
 * per slice, starting at the first row where none of its columns are already
 * taken. Runs on disjoint columns share rows; runs that collide stack.
 *
 * Falls back to `deriveLinkGrid` for data with no pipe allocation at all.
 *
 * @returns {{vpu, fitted, blocks, rowsUsed, overflow, spare, placement}[]}
 */
export function buildLinkGrid(mixers) {
  const anyPipes = Object.values(mixers || {}).some(
    (r) => r && r.isEnabled && reportedColumns(r).length,
  );
  if (!anyPipes) {
    return deriveLinkGrid(mixers).map((g) => ({ ...g, placement: 'derived' }));
  }

  const out = [];
  for (let p = 1; p <= PROCESSORS; p++) {
    const ids = MIXER_IDS.filter((id) => parseMixerId(id).processor === p);
    const fitted = ids.some((id) => mixers?.[id]?.isAvailable);
    const enabled = ids.filter((id) => mixers?.[id]?.isEnabled);

    const runs = [];
    const index = new Map();
    for (const id of enabled) {
      const m = mixers[id];
      const key = `${m.usedInScreen} ${m.usedInLayer}`;
      if (!index.has(key)) {
        index.set(key, runs.length);
        runs.push({
          screen: m.usedInScreen,
          layer: m.usedInLayer,
          capability: m.capability,
          cells: [],
        });
      }
      // Columns are per MIXER, not per run: a layer spread over more than four
      // output links uses a second mixer on a different set of links (§5.5.4),
      // and the two report different pipes.
      runs[index.get(key)].cells.push({ id, slice: m.slice, cols: reportedColumns(m), rec: m });
    }
    for (const r of runs) r.cells.sort((a, b) => a.slice - b.slice || a.id.localeCompare(b.id));

    const taken = new Set();
    const key = (r, c) => `${r},${c}`;
    const blocks = [];
    let rowsUsed = 0;

    for (const run of runs) {
      // One row per distinct slice. Several mixers can share a slice — that is
      // the same strip of picture carried over different output links — and
      // they sit on the same row because their columns do not overlap.
      const slices = [...new Set(run.cells.map((c) => c.slice))].sort((a, b) => a - b);
      const rowOf = new Map(slices.map((s, i) => [s, i]));
      const height = slices.length;
      const allCols = [...new Set(run.cells.flatMap((c) => (c.cols.length ? c.cols : [0])))];

      // First offset where every column this run touches is free for its height.
      let start = 0;
      while (start + height <= LINKS_PER_VPU) {
        const clash = allCols.some((c) => {
          for (let r = start; r < start + height; r++) if (taken.has(key(r, c))) return true;
          return false;
        });
        if (!clash) break;
        start++;
      }

      for (const cell of run.cells) {
        const cols = cell.cols.length ? cell.cols : [0];
        const row = start + rowOf.get(cell.slice);
        for (const c of cols) taken.add(key(row, c));
        blocks.push({
          mixer: cell.id,
          screen: run.screen,
          layer: run.layer,
          capability: cell.rec.capability,
          cutnfill: cell.rec.cutnfillCapa,
          slice: cell.slice,
          row,
          cols,
          size: 1,
          crossesBoundary: cols.some((c) => c >= SCALING_ENGINE_BOUNDARY),
          spansBoundary:
            cols.some((c) => c < SCALING_ENGINE_BOUNDARY) &&
            cols.some((c) => c >= SCALING_ENGINE_BOUNDARY),
        });
      }
      rowsUsed = Math.max(rowsUsed, start + height);
    }

    out.push({
      vpu: p,
      fitted,
      blocks,
      rowsUsed,
      overflow: rowsUsed > LINKS_PER_VPU,
      spare: ids.filter((id) => mixers?.[id]?.isAvailable && !mixers[id].isEnabled).length,
      placement: 'reported-columns',
    });
  }
  return out;
}

/**
 * Lay the enabled mixers of every processor onto its 8x8 link field.
 *
 * Fallback for data with no output-pipe allocation — see buildLinkGrid, which
 * uses the device's own columns when they are there.
 *
 * @returns {{vpu:number, fitted:boolean, blocks:Array, rowsUsed:number}[]}
 *   blocks are `{screen, layer, slice, capability, col, row, size, wrapped}`
 *   in LINK units, so a renderer can draw straight onto an 8x8 field.
 */
export function deriveLinkGrid(mixers) {
  const out = [];

  for (let p = 1; p <= PROCESSORS; p++) {
    const ids = MIXER_IDS.filter((id) => parseMixerId(id).processor === p);
    const fitted = ids.some((id) => mixers?.[id]?.isAvailable);
    const enabled = ids.filter((id) => mixers?.[id]?.isEnabled);

    // Preserve the device's own ordering of (screen, layer) runs.
    const runs = [];
    const index = new Map();
    for (const id of enabled) {
      const m = mixers[id];
      const key = `${m.usedInScreen} ${m.usedInLayer}`;
      if (!index.has(key)) {
        index.set(key, runs.length);
        runs.push({ screen: m.usedInScreen, layer: m.usedInLayer, capability: m.capability, cells: [] });
      }
      runs[index.get(key)].cells.push({ id, slice: m.slice });
    }
    for (const r of runs) r.cells.sort((a, b) => a.slice - b.slice);

    const blocks = [];
    let row = 0;
    for (const run of runs) {
      const size = capacityToLinks(run.capability) || 1;
      // The field is 8 links wide, so this many blocks sit on one layer link.
      const perBand = Math.max(1, Math.floor(LINKS_PER_VPU / size));
      run.cells.forEach((cell, i) => {
        const band = Math.floor(i / perBand);
        const col = (i % perBand) * size;
        blocks.push({
          mixer: cell.id,
          screen: run.screen,
          layer: run.layer,
          capability: run.capability,
          slice: cell.slice,
          col,
          row: row + band * size,
          size,
          // Occupies an additional layer link beyond the run's first (§5.5.4).
          wrapped: band > 0,
          // Sits past the scaling-engine boundary of 4 output links.
          crossesBoundary: col >= SCALING_ENGINE_BOUNDARY,
        });
      });
      const bands = Math.max(1, Math.ceil(run.cells.length / perBand));
      row += bands * size;
    }

    out.push({
      vpu: p,
      fitted,
      blocks,
      rowsUsed: row,
      overflow: row > LINKS_PER_VPU,
      spare: ids.filter((id) => mixers?.[id]?.isAvailable && !mixers[id].isEnabled).length,
    });
  }

  return out;
}

/**
 * Which VPUs host a screen in Optimized mode.
 *
 * §5.5.6: Optimized mode is enabled for the WHOLE VPU when one screen on it uses
 * at least 5 output links and at least one layer of capacity 2, and it removes
 * the 4-output scaling-engine boundary. So the boundary belongs to the VPU, not
 * to the screen that triggered it, and a grid that draws it on an optimized VPU
 * is showing a constraint the device is not applying.
 *
 * `isOptimized` is reported per screen, so map screen -> its mixers -> their
 * processors. On the captured Aquilon C, S1 spends 6 output capabilities and
 * duly reports true, which makes VPU 1 optimized.
 */
export function optimizedVpus(mixers, screenStatus) {
  const optimised = new Set(
    Object.entries(screenStatus || {})
      .filter(([, st]) => st && st.isOptimized)
      .map(([id]) => id),
  );
  const vpus = new Set();
  if (!optimised.size) return vpus;
  for (const [id, rec] of Object.entries(mixers || {})) {
    if (!rec || !rec.isEnabled) continue;
    if (!optimised.has(String(rec.usedInScreen))) continue;
    const parsed = parseMixerId(id);
    if (parsed) vpus.add(parsed.processor);
  }
  return vpus;
}

/**
 * Which mixers differ between the running mapping and the staged one.
 *
 * The output links matter as much as the properties — a staged configuration
 * can move a layer onto different links while every other value stays put, and
 * comparing only `@props` reports that as no change at all. On the captured
 * Aquilon C the running map interleaves S1 across links 1 and 3 while the
 * staged one packs it onto 1 and 2, and nothing else differs.
 */
export function diff(current, next) {
  const out = [];
  for (const id of MIXER_IDS) {
    const a = (current || {})[id];
    const b = (next || {})[id];
    if (!a && !b) continue;
    const changed = [];

    for (const p of ['isAvailable', ...MIXER_PROPS]) {
      const av = a ? a[p] : undefined;
      const bv = b ? b[p] : undefined;
      if (av !== bv) changed.push({ prop: p, from: av, to: bv });
    }

    const pipeOf = (rec, k) => {
      const v = rec && rec.mixerAllocation ? rec.mixerAllocation[`usedOnOutPipe${k}`] : undefined;
      return v === 'NONE' ? undefined : v;
    };
    for (let k = 1; k <= OUT_PIPES; k++) {
      const av = pipeOf(a, k);
      const bv = pipeOf(b, k);
      if (av !== bv) {
        changed.push({ prop: `link ${k}`, from: av ?? '—', to: bv ?? '—' });
      }
    }

    if (changed.length) out.push({ mixer: id, changed });
  }
  return out;
}
